import express from 'express';
import crypto from 'crypto';

const app = express();

// Capture raw body for signature verification
app.post('/webhooks/linear', express.raw({ type: 'application/json' }), (req, res) => {
  const signature = req.headers['x-linear-signature'] as string;
  const rawBody = req.body.toString('utf-8');
  const secret = process.env.LINEAR_WEBHOOK_SECRET!;

  const expectedSignature = crypto
    .createHmac('sha256', secret)
    .update(rawBody)
    .digest('hex');

  if (signature !== expectedSignature) {
    return res.status(401).send('Unauthorized: Invalid HMAC signature');
  }

  const event = JSON.parse(rawBody);
  console.log(`Verified Linear Event: ${event.action} on ${event.type}`);

  // Forward to Slack dispatcher
  res.status(200).json({ status: 'queued' });
});

