import time
import requests

def post_to_slack(webhook_url, blocks, max_retries=3):
    headers = {"Content-Type": "application/json"}
    payload = {"blocks": blocks}

    for attempt in range(max_retries):
        res = requests.post(webhook_url, json=payload, headers=headers)
        if res.status_code == 200:
            return True
        elif res.status_code == 429:
            retry_after = int(res.headers.get("Retry-After", 2))
            print(f"Slack rate limit hit. Sleeping for {retry_after}s...")
            time.sleep(retry_after)
        else:
            res.raise_for_status()

    raise RuntimeError("Failed to dispatch notification to Slack after retries")
